"use strict";(self.webpackChunkmantis_docs=self.webpackChunkmantis_docs||[]).push([[635],{1924:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>r,default:()=>d,frontMatter:()=>o,metadata:()=>a,toc:()=>l});var s=n(4848),i=n(8453);const o={sidebar_position:1},r="The Mantis Protocol",a={id:"protocol/mantis",title:"The Mantis Protocol",description:"On the Mantis rollup resides the Mantis protocol that facilitates optimal execution of cross-domain intent via a competition of solvers. In this protocol, users sign intents which are contained on a private rollup mempool. Solvers are staked agents that can a) observe the intents in the mempool and b) post solutions to intents in the auctioneer contract. The auctioneer contract scores the solutions based on how well they fit constraints the user has set. The winner of the auction is responsible for settling the intent solution they have proposed.",source:"@site/docs/protocol/mantis.md",sourceDirName:"protocol",slug:"/protocol/mantis",permalink:"/protocol/mantis",draft:!1,unlisted:!1,editUrl:"https://github.com/ComposableFi/mantis-docs/docs/protocol/mantis.md",tags:[],version:"current",sidebarPosition:1,frontMatter:{sidebar_position:1},sidebar:"protocol",next:{title:"Intent Lifecycle",permalink:"/protocol/intent-lifecycle"}},c={},l=[{value:"Smart Contracts on Each Chain",id:"smart-contracts-on-each-chain",level:2},{value:"Mantis V1",id:"mantis-v1",level:2},{value:"Trust Assumptions",id:"trust-assumptions",level:2}];function h(e){const t={a:"a",h1:"h1",h2:"h2",header:"header",img:"img",li:"li",ol:"ol",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"the-mantis-protocol",children:"The Mantis Protocol"})}),"\n",(0,s.jsx)(t.p,{children:"On the Mantis rollup resides the Mantis protocol that facilitates optimal execution of cross-domain intent via a competition of solvers. In this protocol, users sign intents which are contained on a private rollup mempool. Solvers are staked agents that can a) observe the intents in the mempool and b) post solutions to intents in the auctioneer contract. The auctioneer contract scores the solutions based on how well they fit constraints the user has set. The winner of the auction is responsible for settling the intent solution they have proposed."}),"\n",(0,s.jsx)(t.h2,{id:"smart-contracts-on-each-chain",children:"Smart Contracts on Each Chain"}),"\n",(0,s.jsx)(t.p,{children:"Each blockchain supported by Mantis hosts an escrow contract that facilitates the intent system. It is possible to interact with the Mantis protocol directly through these contracts."}),"\n",(0,s.jsx)(t.p,{children:"These contracts provide the following interfaces:"}),"\n",(0,s.jsxs)(t.ol,{children:["\n",(0,s.jsx)(t.li,{children:"escrowFundsAndSubmitIntent(IntentData) -> UInt: Allows users to submit a new intent by locking their funds in the contract. It generates a unique ID for the intent, stores the associated data, and emits an event containing the intent ID for off-chain entities to detect. The IntentData includes fields such as token, amount, user, outputToken, and receiverAddress."}),"\n",(0,s.jsx)(t.li,{children:"updateIntent(IntentId: UInt, amountOut: UInt, winnerSolver: Address): Callable only by the Auctioneer, this function updates the intent with the winning Solver's address and the finalized output amount."}),"\n",(0,s.jsx)(t.li,{children:"releaseFunds(SolverTransfer): Callable only by the winning Solver, this function releases the locked funds to the recipient account. The SolverTransfer contains details necessary to execute the fund transfer."}),"\n",(0,s.jsx)(t.li,{children:"onReceiveTransfer(TransferData, PacketData) -> bool: A callback function for handling cross-chain intents received via Inter-Blockchain Communication (IBC). It processes incoming ICS20-transfer packets, updating the contract state accordingly, and returns a boolean indicating the success of the operation."}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"Each contract has 3 main functions:"}),"\n",(0,s.jsxs)(t.ol,{children:["\n",(0,s.jsx)(t.li,{children:"`escrowFundsAndSubmitIntent(IntentData) -> UInt`. Through this function a user can submit a new intent (e.g. a swap request). It will generate a new ID for the intent and store the data inside the contract, emitting an event with the ID."}),"\n",(0,s.jsx)(t.li,{children:"`updateIntent(IntentId, amountOut: UInt, winnerSolver: Address)`. This funciton is only callable by auctioneers and is used to refine information about the intent."}),"\n",(0,s.jsx)(t.li,{children:"`releaseFunds(SolverTransfer)`. This function is called by a solver that decided to process the intent, in particular, this will release the funds to the recipient account."}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"More details about the code can be found along the links:"}),"\n",(0,s.jsxs)(t.table,{children:[(0,s.jsx)(t.thead,{children:(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.th,{children:(0,s.jsx)(t.strong,{children:"Chain"})}),(0,s.jsx)(t.th,{children:(0,s.jsx)(t.strong,{children:"Sources"})})]})}),(0,s.jsxs)(t.tbody,{children:[(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Ethereum"}),(0,s.jsx)(t.td,{children:"0x64E78873057769a5fd9A2278E6820666ec7e87f9"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Mantis/Solana"}),(0,s.jsx)(t.td,{children:(0,s.jsx)(t.a,{href:"https://github.com/ComposableFi/emulated-light-client/blob/upgrade/solana/bridge-escrow/programs/bridge-escrow/src/lib.rs",children:"AhfoGVmS19tvkEG2hBuZJ1D6qYEjyFmXZ1qPoFD6H4Mj"})})]})]})]}),"\n",(0,s.jsx)(t.h2,{id:"mantis-v1",children:"Mantis V1"}),"\n",(0,s.jsx)(t.p,{children:"In its first iteration, Mantis will accept intents for swaps between Ethereum and Solana (cross-chain intents) as well as swaps just on Ethereum or just on Solana (single-domain intents):"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Single-Domain Intents:"})," These are transactions executed entirely within a single blockchain network. The user submits an intent on Ethereum or Solana. Then, the solver provides a solution to the user on the network of choice via the Mantis contract and funds are released to the recipient. Use cases currently include asset swaps within the same blockchain."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Cross-Chain Intents"}),": These involve transactions that transfer assets between different blockchain networks. The user submits an intent on the source chain. Then, the Solver provides a solution to the user on the destination chain and the Mantis contract coordinates cross-chain communication via IBC to release funds to the Solver on the source chain. Use cases include swapping assets from one chain to another."]}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"The architecture of Mantis v1 is as follows:"}),"\n",(0,s.jsxs)(t.ol,{children:["\n",(0,s.jsx)(t.li,{children:"Intents (preferences for a cross-chain transaction) are submitted to the Mantis interface via the Mantis rollup directly or via another IBC-connected chain like Solana or Ethereum."}),"\n",(0,s.jsx)(t.li,{children:"User funds are escrowed on the source chain or the rollup (where the intent is submitted)."}),"\n",(0,s.jsx)(t.li,{children:"All intents then flow to the Mantis rollup. From here, a smart contract on the Mantis rollup sends intents to an off-chain auctioneer."}),"\n",(0,s.jsx)(t.li,{children:"Information on intents is sent to solvers."}),"\n",(0,s.jsx)(t.li,{children:"Solvers submit solutions (e.g. the output amount of a swap) for user intents to the rollup."}),"\n",(0,s.jsx)(t.li,{children:"Solutions are scored off-chain by the auctioneer."}),"\n",(0,s.jsx)(t.li,{children:"Once the winning solution is determined, the solver that proposed it must execute the intent. The solver makes the necessary state transitions to the respective destination chains."}),"\n",(0,s.jsx)(t.li,{children:"Once the intent solution is executed, proof of success is sent to the rollup and the source chain via IBC."}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"This architectural flow is summarized below:"}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.img,{alt:"mantis",src:n(3581).A+"",width:"1600",height:"510"})}),"\n",(0,s.jsx)(t.h2,{id:"trust-assumptions",children:"Trust Assumptions"}),"\n",(0,s.jsx)(t.p,{children:"Trust assumptions of Mantis include:"}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"The IBC Protocol:"})}),"\n",(0,s.jsxs)(t.p,{children:["IBC is used on Mantis as a trustless cross-domain messaging protocol for proving specific occurrences happened on different domains. IBC was selected as Mantis\u2019s mechanism for cross-chain operations because it is trust-minimized. However, Mantis still places trust in the IBC protocol itself. An explanation of IBC\u2019s trust minimization compared to other bridging mechanisms is available ",(0,s.jsx)(t.a,{href:"https://medium.com/@Picasso_Network/ibc-as-the-end-game-of-bridging-a-comparison-analysis-on-trust-dcc01e0d9377",children:"here"}),"."]}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"The Auctioneer:"})}),"\n",(0,s.jsx)(t.p,{children:"On Mantis, trust is placed in the auctioneer (initially, an off-chain actor) to deposit escrowed user funds. However, the auctioneer's power is limited in scope. They can, at most, censor intents and solutions. They do not hold users' funds at any point in the process. Once a solver submits a solution, proof of this submission is made via IBC. This eliminates the need for trust in the auctioneer at this stage."}),"\n",(0,s.jsx)(t.p,{children:"The interests of the auctioneer are generally aligned with those of solvers and users. Better solutions typically result in higher fees paid to the auctioneer. The result is an incentive for fair and efficient operation. While off-chain agreements between solvers and the auctioneer are theoretically possible, such collusion would likely be statistically observable by other solvers. This provides a form of checks and balances within the system."}),"\n",(0,s.jsx)(t.p,{children:"This structure aims to create a trustless or trust-minimized environment where the auctioneer's role is important but constrained. Moreover, multiple parties have incentives to maintain the integrity of the system."})]})}function d(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(h,{...e})}):h(e)}},3581:(e,t,n)=>{n.d(t,{A:()=>s});const s=n.p+"assets/images/protocol-a695e08033306c17bc18e438fe404ef7.png"},8453:(e,t,n)=>{n.d(t,{R:()=>r,x:()=>a});var s=n(6540);const i={},o=s.createContext(i);function r(e){const t=s.useContext(o);return s.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),s.createElement(o.Provider,{value:t},e.children)}}}]);